        acc_f += tl.dot(x_tile, tl.trans(w_f), input_precision="tf32x3")
        acc_g += tl.dot(x_tile, tl.trans(w_g), input_precision="tf32x3")
        acc_o += tl.dot(x_tile, tl.trans(w_o), input_precision="tf32x3")

