        acc_f += tl.load(b_hh_ptr + hidden_size + offs_n, mask=n_mask, other=0.0).to(
            tl.float32
        )[None, :]
        acc_g += tl.load(
            b_hh_ptr + 2 * hidden_size + offs_n, mask=n_mask, other=0.0
        ).to(tl.float32)[None, :]
        acc_o += tl.load(
            b_hh_ptr + 3 * hidden_size + offs_n, mask=n_mask, other=0.0
        ).to(tl.float32)[None, :]

