def _unpack_cell_params(param, device, dtype, cache):
    """Pull dequantized w_ih / w_hh / b_ih / b_hh out of one layer's params.

    aten::quantized_lstm takes its weights either as CellParamsBase script
    objects (the .input overload) or as a flat tensor list (the deprecated
    .input_legacy overload). CellParamsBase keeps the weights inside prepacked
    linear handles, so recover them through linear_unpack and dequantize; the
    int8 rounding is already baked into the stored values and is preserved.

    The prepacked weights live on the host, so unpacking involves a host copy.
    Results are cached per params object, keyed by device and dtype: the
    weights are constant across timesteps and calls, and repeating the copy
    would both waste bandwidth and make the op unusable under CUDA graph
    capture.
    """
    key = (id(param), device, dtype)
    hit = cache.get(key)
    if hit is not None:
        return hit

    if isinstance(param, torch.ScriptObject):
        state = param.__getstate__()[0]
        biases, packed = state[1], state[4]
        w_ih = torch.ops.quantized.linear_unpack(packed[0])[0].dequantize()
        w_hh = torch.ops.quantized.linear_unpack(packed[1])[0].dequantize()
        b_ih = biases[0] if len(biases) > 0 else None
        b_hh = biases[1] if len(biases) > 1 else None
    else:
        w_ih, w_hh = param[0], param[1]
        if w_ih.is_quantized:
            w_ih = w_ih.dequantize()
        if w_hh.is_quantized:
            w_hh = w_hh.dequantize()
        b_ih = param[2] if len(param) > 2 else None
        b_hh = param[3] if len(param) > 3 else None

    w_ih = w_ih.to(device=device, dtype=dtype).contiguous()
    w_hh = w_hh.to(device=device, dtype=dtype).contiguous()
    if b_ih is not None:
        b_ih = b_ih.to(device=device, dtype=dtype).contiguous()
    if b_hh is not None:
        b_hh = b_hh.to(device=device, dtype=dtype).contiguous()

    unpacked = (w_ih, w_hh, b_ih, b_hh)
    # Hold a reference to the source object so the id() key stays valid.
    cache[key] = unpacked
    cache.setdefault("_keepalive", []).append(param)
    return unpacked


def _run_direction(x, h0, c0, w_ih, w_hh, b_ih, b_hh, reverse):
    """Drive the fused step kernel across a sequence in one direction."""
    seq_len, batch_size, input_size = x.shape
    hidden_size = h0.shape[1]
    device, dtype = x.device, x.dtype

    has_bias = b_ih is not None and b_hh is not None
    if not has_bias:
        b_ih = torch.empty(0, device=device, dtype=dtype)
        b_hh = torch.empty(0, device=device, dtype=dtype)

    def grid(META):
        return (
            triton.cdiv(batch_size, META["BLOCK_M"]),
            triton.cdiv(hidden_size, META["BLOCK_N"]),
        )

    outputs = [None] * seq_len
    h, c = h0, c0
    steps = range(seq_len - 1, -1, -1) if reverse else range(seq_len)
    for t in steps:
        x_t = x[t].contiguous()
        hy = torch.empty((batch_size, hidden_size), device=device, dtype=dtype)
        cy = torch.empty((batch_size, hidden_size), device=device, dtype=dtype)

        quantized_lstm_step_kernel[grid](
            x_t,
            h,
            c,
            w_ih,
            w_hh,
            b_ih,
            b_hh,
            hy,
            cy,
            batch_size,
            input_size,
            hidden_size,
            x_t.stride(0),
            x_t.stride(1),
            h.stride(0),
            h.stride(1),
            c.stride(0),
            c.stride(1),
            w_ih.stride(0),
            w_ih.stride(1),
            w_hh.stride(0),
            w_hh.stride(1),
            hy.stride(0),
            hy.stride(1),
            cy.stride(0),
            cy.stride(1),
            HAS_BIAS=has_bias,
        )

        h, c = hy, cy
        outputs[t] = hy

    return torch.stack(outputs), h, c


def quantized_lstm(
    input,
    hx,
    params,
    has_biases,
    num_layers,
    dropout,
    train,
    bidirectional,
    batch_first,
    dtype=None,
    use_dynamic=False,
):
    """Quantized LSTM built on a fused Triton timestep kernel.

    The reference aten::quantized_lstm has no CUDA kernel, so the quantized
    weights are dequantized once up front and every timestep then runs through
    the fused kernel on device. Quantization error stays in the result because
    the dequantized values still carry the int8 rounding.

    Args:
        input: (seq_len, batch, input_size), or (batch, seq_len, input_size)
            when batch_first is set.
        hx: [h0, c0], each (num_layers * num_directions, batch, hidden_size).
        params: Per-layer weights, either CellParamsBase script objects or
            flat [w_ih, w_hh, b_ih, b_hh] tensor lists.
        has_biases: Whether each layer carries b_ih and b_hh.
        num_layers: Number of stacked layers.
        dropout: Inter-layer dropout probability, applied only when train.
        train: Whether dropout is active.
        bidirectional: Whether to run a second, reversed direction per layer.
        batch_first: Whether input and output put batch on dim 0.
        dtype: Accepted for aten schema compatibility; ignored.
        use_dynamic: Accepted for aten schema compatibility; ignored.

    Returns:
        output: (seq_len, batch, num_directions * hidden_size), transposed back
            when batch_first is set.
        hy, cy: Final states, each matching the layout of the h0 and c0 inputs.
    """
    logger.debug("GEMS QUANTIZED_LSTM")

    cache = _PARAM_CACHE

    if batch_first:
        input = input.transpose(0, 1)
    input = input.contiguous()

    h0, c0 = hx[0], hx[1]
    num_directions = 2 if bidirectional else 1
    params_per_layer = len(params) // num_layers

    layer_input = input
    h_final = []
    c_final = []

    for layer in range(num_layers):
        dir_outputs = []
        for direction in range(num_directions):
            idx = layer * num_directions + direction
            param = params[layer * params_per_layer + direction]
            w_ih, w_hh, b_ih, b_hh = _unpack_cell_params(
                param, input.device, input.dtype, cache
            )
            if not has_biases:
                b_ih, b_hh = None, None

            out, hy, cy = _run_direction(
                layer_input,
                h0[idx].contiguous(),
                c0[idx].contiguous(),
                w_ih,
                w_hh,
                b_ih,
                b_hh,
                reverse=(direction == 1),
            )
            dir_outputs.append(out)
            h_final.append(hy)
            c_final.append(cy)

        layer_input = (
            dir_outputs[0] if num_directions == 1 else torch.cat(dir_outputs, dim=-1)
        )

        # Dropout applies between layers only, never after the last one.
        if train and dropout > 0.0 and layer < num_layers - 1:
            layer_input = torch.nn.functional.dropout(
                layer_input, p=dropout, training=True
            )

    output = layer_input
    if batch_first:
        output = output.transpose(0, 1)

    return output, torch.stack(h_final), torch.stack(c_final)
